import {gate142,prepareFrame142} from './resource-gate142.js?v=150';
// Lazily loaded inspection: no second WebGL renderer or animation while closed.
const doc=document;
let dialog,viewer,loading,wasRunning=false,priorPause='false',openedAt=0,opener;
function state(){return window.metroViewState?.()||{};}
function makeDialog(){
 dialog=doc.createElement('dialog');dialog.id='sr126-dialog';dialog.setAttribute('aria-labelledby','sr126-heading');dialog.innerHTML=`<div class="sr126-header"><div><small>INFRAESTRUCTURA · INSPECCIÓN 3D</small><h2 id="sr126-heading">Subestación rectificadora</h2></div><button data-sr-close aria-label="Cerrar inspección de la subestación">Volver ×</button></div><div class="sr128-mode-tabs" role="group" aria-label="Apartados de subestaciones"><button data-sr-explore-mode aria-pressed="true">Explorar</button><button data-sr-maintain-mode aria-pressed="false" disabled>Mantenimiento</button></div><div class="sr126-layout"><section class="sr126-viewport"><div class="sr126-tools" role="group" aria-label="Vistas de la subestación"><button data-sr-home>Maqueta completa</button><button data-sr-entry aria-pressed="true">Entrar al local</button><button data-sr-navigation="orbit" aria-pressed="true">Girar</button><button data-sr-navigation="pan" aria-pressed="false">PAN · desplazar</button><details class="sr137-advanced"><summary>Más vistas</summary><div><button data-sr-interior aria-pressed="true">Interior</button><button data-sr-explode aria-pressed="false">Despiece</button><button data-sr-isolate disabled aria-pressed="false">Aislar conjunto</button><button data-sr-doors aria-pressed="true">Abrir gabinetes</button><label class="sr134-light">Luz <input data-sr-light type="range" min="0.85" max="1.55" step="0.05" value="1.10" aria-label="Intensidad visual de iluminación"></label></div></details></div><div class="sr126-stage"><canvas aria-label="Interior 3D de una subestación rectificadora"></canvas></div><p data-sr-status role="status">Preparando el interior 3D…</p></section><aside class="sr126-panel"><div data-sr-explore><p class="sr126-kicker">EXPLORA LOS 12 CONJUNTOS</p><details><summary>Los 12 conjuntos</summary><nav data-sr-list aria-label="Componentes de la subestación"></nav></details><details><summary>Gabinetes y puertas</summary><section data-sr-cabinets class="sr135-cabinets"></section></details><article><h3 data-sr-title>Interior de tracción</h3><b data-sr-subtitle></b><p data-sr-description></p></article><details><summary>Normas mexicanas y alcance</summary><p>Señalización: NOM-026-STPS-2008. Iluminación del centro de trabajo: NOM-025-STPS-2008. Mantenimiento: NOM-029-STPS-2011.</p><p>La NOM-001-SEDE-2012, numeral 1.2.2(c), excluye las instalaciones dedicadas exclusivamente al equipo rodante y a su señalización/comunicación. No se aplica aquí como certificación de la tracción. Los servicios de utilización requieren revisar su alcance particular.</p><p>Pasillos y acceso despejados, resguardos, alumbrado y señales se representan con finalidad didáctica. El brillo de pantalla no equivale a lux medidos. La disposición no es un proyecto constructivo ni un dictamen.</p><a href="https://dof.gob.mx/nota_detalle_popup.php?codigo=5280607" target="_blank" rel="noopener">NOM-001-SEDE · alcance</a><br><a href="https://dof.gob.mx/normasOficiales/3541/stps.htm" target="_blank" rel="noopener">NOM-026 · señalización</a><br><a href="https://dof.gob.mx/normasOficiales/3581/stps.htm" target="_blank" rel="noopener">NOM-025 · iluminación</a><br><a href="https://dof.gob.mx/normasOficiales/4589/STPS9a/STPS9a.htm" target="_blank" rel="noopener">NOM-029 · mantenimiento</a></details><details><summary>Esquema y documentación</summary><p>CA → celdas MT → transformador de doble secundario → rectificador → distribución CD → tracción. El retorno de tracción y PE se representan separados.</p><p>Base: METRO.pdf, páginas 14–16, y los tres despieces que compartiste. Complemento técnico: documentación ABB Enviline TDR/WDR.</p><p>Modelo didáctico general. No representa el levantamiento, la cantidad ni la ubicación de una subestación concreta. Los locales SAF del recorrido conservan su función de alumbrado y fuerza.</p><a href="https://library.e.abb.com/public/2435f4fd81c44b39ac28bfec91542945/Enviline%20TDR,%20WDR%20EN.pdf" target="_blank" rel="noopener">Referencia técnica ABB</a></details></div><section data-sr-maintenance-root hidden></section></aside></div>`;doc.body.append(dialog);
 dialog.querySelector('[data-sr-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{viewer?.stop();doc.body.dataset.pause105=priorPause;if(priorPause!=='true')window.dispatchEvent(new CustomEvent('metro-resume105',{detail:{elapsed:performance.now()-openedAt}}));if(wasRunning&&!state().running&&doc.body.dataset.workspace==='simulation')doc.getElementById('play')?.click();wasRunning=false;opener?.focus();});
}
async function open(e){if(!dialog)makeDialog();if(dialog.open)return;opener=e?.currentTarget||doc.activeElement;wasRunning=doc.body.dataset.workspace==='simulation'&&!!state().running;priorPause=doc.body.dataset.pause105||'false';openedAt=performance.now();if(wasRunning)doc.getElementById('play')?.click();dialog.showModal();doc.body.dataset.pause105='true';return gate142('Subestación rectificadora',async()=>{try{dialog.querySelector('[data-sr-status]').textContent='Cargando modelo de Blender y materiales…';if(!viewer){loading||=import('./rectifier-view126.js?v=194');const {RectifierView126}=await loading;viewer=await RectifierView126.create(dialog);}if(dialog.open){viewer.start();await prepareFrame142(viewer);if(!viewer.service128?.active)dialog.querySelector('[data-sr-status]').textContent='Haz clic sobre una puerta para abrir o cerrar su gabinete · PAN: rueda presionada y arrastrar · rueda: zoom.';}}catch(err){dialog.querySelector('[data-sr-status]').textContent='No se pudo abrir el interior 3D. Puedes volver al simulador y reintentar.';console.error('SR126',err);throw err;}},{host:dialog});}
function install(){for(const [selector,id]of[['.g105-context-actions','sr126-workshop'],['.game-depot-heading > div','sr126-depot']]){const parent=doc.querySelector(selector);if(!parent||doc.getElementById(id))continue;const b=doc.createElement('button');b.id=id;b.type='button';b.className='sr126-open';b.textContent='Subestación rectificadora';b.addEventListener('click',open);parent.append(b);}}
install();const observer=new MutationObserver(install);observer.observe(doc.body,{childList:true,subtree:true});

window.metroSubstations127={open};
